using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;
using AntColony.Core;using AntColony.Buildings;using AntColony.Data;using AntColony.Save;using AntColony.UI;using UnityEngine;
public static class RoomRoof1115Checks {
 public static string TemplateInfo(){var t=(GameObject)typeof(BuildingPlacementController).GetMethod("GetTemplate",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{BuildingKind.SoilWall,UnitRole.Worker});return t.name+" scale="+t.transform.localScale+" bounds="+t.GetComponent<Renderer>().bounds;}
 const string Dir="work/colony-polish-1115/";
 static void Check(bool ok,string text){File.AppendAllText(Dir+"room-roof.txt",(ok?"PASS ":"FAIL ")+text+"\n");if(!ok)throw new Exception(text);}
 public static string Main(){File.WriteAllText(Dir+"room-roof.txt","Isolated supplied room fixture. Natural campaign checkpoint is untouched.\n");_=Run();return "Room roof checks started";}
 public static string HeightAudit(){var walls=UnityEngine.Object.FindObjectsByType<SoilWall>(FindObjectsInactive.Include).Where(w=>w.transform.position.x>10).ToArray();foreach(var w in walls)w.gameObject.SetActive(true);RoomSystem.MarkDirty();var rooms=RoomSystem.Rooms;var roof=UnityEngine.Object.FindAnyObjectByType<RoomRoofs>();return "WallTop method="+(typeof(RoomRoofs).GetMethod("WallTop",BindingFlags.NonPublic|BindingFlags.Static)!=null)+"\n"+string.Join("\n",walls.Select(w=>"wall "+w.Position+" model="+w.GetComponent<FacilityVisual>()?.Model+" bounds="+string.Join(";",w.GetComponent<FacilityVisual>().Model.GetComponentsInChildren<Renderer>().Select(r=>r.bounds.ToString()))))+"\nRoof "+string.Join(";",roof.GetComponentsInChildren<Renderer>().Select(r=>r.bounds.ToString()));}
 static async Task Ready(){var end=DateTime.UtcNow.AddSeconds(120);while(SaveSystem.Busy&&DateTime.UtcNow<end)await Task.Delay(100);Check(!SaveSystem.Busy,"Scene ready");}
 static GameObject Wall(Vector3 p,bool side=false){var template=(GameObject)typeof(BuildingPlacementController).GetMethod("GetTemplate",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{BuildingKind.SoilWall,UnitRole.Worker});var go=UnityEngine.Object.Instantiate(template,p,Quaternion.Euler(0,side?90:0,0));go.SetActive(true);return go;}
 static async Task Run(){var root=SaveStorage.RootOverride;var settings=UserSettings.Current.Clone();try{
 var quiet=settings.Clone();quiet.autoSaveEnabled=false;quiet.autoPauseThreat=false;UserSettings.Apply(quiet,false);SaveStorage.RootOverride=Path.Combine(Application.temporaryCachePath,"RoomRoof1115-"+Guid.NewGuid().ToString("N"));
 await Ready();SaveSystem.NewGame(new NewGameOptions{seed=261115,mapSize=MapSize.Small});await Ready();GameMenuController.Instance.Resume();SimulationPause.UserSpeed(0);
 var home=CommanderRoster.Instance.Commanders.First().Position;int x0=Mathf.FloorToInt(home.x)+12,z0=Mathf.FloorToInt(home.z);
 Physics.SyncTransforms();Check(Physics.Raycast(new Vector3(x0+2,100,z0+2),Vector3.down,out var hit,200,1<<8),"Find actual terrain");float floor=hit.point.y;Check(floor>5,"Nonzero map elevation fixture");
 for(int x=1;x<=5;x+=2){Wall(new Vector3(x0+x,floor+.75f,z0+.5f));Wall(new Vector3(x0+x,floor+.75f,z0+5.5f));} for(int z=2;z<=4;z+=2){Wall(new Vector3(x0+.5f,floor+.75f,z0+z),true);Wall(new Vector3(x0+5.5f,floor+.75f,z0+z),true);}
 Physics.SyncTransforms();await Task.Delay(1000);RoomSystem.MarkDirty();var centre=new Vector3(x0+3,floor,z0+3);var room=RoomSystem.RoomAt(centre);Check(room!=null&&room.Cells.Count==16,"Closed walls form a real sixteen-cell room");await Task.Delay(1000);_ = RoomSystem.Rooms;await Task.Delay(500);
 var roofs=UnityEngine.Object.FindAnyObjectByType<RoomRoofs>();var model=roofs.transform.Cast<Transform>().FirstOrDefault(t=>t.name.StartsWith("Thatch roof"));Check(model!=null,"Rectangular room uses imported Meshy roof");var render=model.GetComponentInChildren<Renderer>();Check(render.bounds.min.y>=floor+1.45f&&render.bounds.max.y<floor+5,"Roof sits on walls above real terrain");Check(model.GetComponentsInChildren<Renderer>().All(r=>r.sharedMaterials.All(m=>m.GetTexture("_BaseMap")!=null)),"Thatch textures survive runtime fade materials");Check(model.GetComponentsInChildren<Collider>().All(c=>!c.enabled),"Roof does not obstruct navigation or clicks");
 var cam=UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>();var restore=typeof(AntColony.Camera.IsometricCameraController).GetMethod("RestoreView",BindingFlags.NonPublic|BindingFlags.Instance);
 restore.Invoke(cam,new object[]{centre,45f,16f});await Task.Delay(500);Check(render.sharedMaterial.GetColor("_BaseColor").a>.8f,"Distant view shows roof");
 restore.Invoke(cam,new object[]{centre,45f,5f});await Task.Delay(500);Check(render.sharedMaterial.GetColor("_BaseColor").a<.2f,"Close view reveals interior");
 // Keep the close framing but make the material opaque for a separate source-model inspection image.
 roofs.enabled=false;foreach(var r in model.GetComponentsInChildren<Renderer>())foreach(var m in r.sharedMaterials)m.SetColor("_BaseColor",Color.white);
 var shaderDeadline=DateTime.UtcNow.AddSeconds(45);while(UnityEditor.ShaderUtil.anythingCompiling&&DateTime.UtcNow<shaderDeadline)await Task.Delay(200);Check(!UnityEditor.ShaderUtil.anythingCompiling,"Shader compilation finishes before visual capture");await Task.Delay(1000);
 ScreenCapture.CaptureScreenshot(Dir+"thatch-roof-close.png");await Task.Delay(800);roofs.enabled=true;await Task.Delay(500);ScreenCapture.CaptureScreenshot(Dir+"thatch-roof-interior.png");await Task.Delay(500);
 Check(SaveSystem.TrySave(false,0,out var error),"Save enclosed room: "+error);Check(SaveSystem.TryLoad(SaveSlots.PathFor(false,0),out error),"Load enclosed room: "+error);await Ready();GameMenuController.Instance.Resume();SimulationPause.UserSpeed(0);RoomSystem.MarkDirty();Check(RoomSystem.RoomAt(centre)?.Cells.Count==16,"Enclosure survives full reload");await Task.Delay(800);roofs=UnityEngine.Object.FindAnyObjectByType<RoomRoofs>();Check(roofs.transform.Cast<Transform>().Any(t=>t.name.StartsWith("Thatch roof")),"Meshy roof rebuilds after load");
 Wall(new Vector3(x0+2,floor+.75f,z0+1.5f));Physics.SyncTransforms();RoomSystem.MarkDirty();room=RoomSystem.RoomAt(centre);Check(room!=null&&room.Cells.Count==14,"Concave room retains uncovered corner");await Task.Delay(800);var flat=roofs.GetComponentsInChildren<MeshFilter>().Single();Check(flat.sharedMesh.vertexCount==56&&flat.sharedMesh.vertices.All(v=>v.y>floor+1.4f),"Irregular fallback covers exactly occupied cells above ground");
 var opening=SceneObjects.All<SoilWall>().First(w=>Mathf.Abs(w.Position.x-(x0+.5f))<.1f&&Mathf.Abs(w.Position.z-(z0+2))<.1f);opening.gameObject.SetActive(false);RoomSystem.MarkDirty();Check(RoomSystem.RoomAt(centre)==null&&RoomRoofs.Count==0,"Opening boundary removes room and roof");
 }catch(Exception e){File.AppendAllText(Dir+"room-roof.txt","ERROR "+e+"\n");}finally{SimulationPause.UserSpeed(0);UserSettings.Apply(settings,false);SaveStorage.RootOverride=root;File.AppendAllText(Dir+"room-roof.txt","RESTORED\n");}}
}
